<?php require __DIR__.'/includes/bootstrap.php';logged();$error='';try{$movies=search_movies($_GET);}catch(InvalidArgumentException $e){$movies=[];$error=$e->getMessage();}$genres=$db->query('SELECT DISTINCT Genre FROM movies ORDER BY Genre')->fetchAll(PDO::FETCH_COLUMN);$years=$db->query('SELECT DISTINCT YEAR(Date_of_release) FROM movies ORDER BY 1 DESC')->fetchAll(PDO::FETCH_COLUMN);$filters=[];foreach(['name','genre','year','price'] as $k)$filters[$k]=input($_GET,$k);render('movies.twig',compact('movies','genres','years','filters','error'));
